            '"숨을 참고 힘을 주면 어떻게 될까요?" 숨을 참으면 어지러울 수 있다는 점을 짚는다. 근력은 한 번에 내는 힘, 근지구력은 오래 되풀이하는 힘이라는 3차시 정리를 다시 쓰게 한다.',
