            '"공을 튀기며 걷는 일은 균형만 필요한가요, 눈과 손이 함께 움직이는 힘도 필요한가요?" 협응성이 눈·손·발이 함께 움직이는 힘임을 짚는다. 속도를 올리려는 학생에게 "방향을 바꿀 때 무릎을 살짝 굽히면 몸이 안정돼요"라고 말한다.',
