            '"계획표에 \'친구 점수\' 칸이 꼭 있어야 할까요?" 계획은 나를 위한 것이므로 내가 기르려는 요소와 내가 해낼 양이 중심이라고 짚는다. 하루 빠진 학생이 다음 날 두 배로 하려는 모습에 "빠진 날은 그대로 두고 다음 날부터 계획대로 해요"라고 말한다.',
