        intro: [
          '교사가 제자리에서 가볍게 달리며 "지금 나는 이야기를 할 수 있고 노래는 어려워요. 이 세기는 어떤가요?"라고 말하고, 이어서 빠르게 달린 뒤 "하나, 둘…" 낱말만 겨우 말해 본다. 두 세기의 차이를 학생이 말하게 한다. 오늘은 말을 할 수 있는지로 운동 세기를 알아보고 조절하는 방법을 정한다고 알린다.',
          '달리면서 이야기할 수 있을 때와 낱말만 겨우 말할 때의 세기는 어떻게 다를까요?',
        ],
