            '운동 동작을 읽고 늘여 주거나 풀어 줘야 할 몸의 부분을 모두 골라요.',
            '"달리기 뒤 가장 오래 일한 곳은 어디였나요?" 달리기에서 다리를 오래 쓴 만큼 다리 부분을 천천히 늘여 주도록 이끈다. 팔 돌리기에서 어깨만 고르려는 학생에게 "팔꿈치와 손목도 같이 움직였나요?"라고 되묻는다. 아프기 전 당김에서 멈추는 약속을 한 번 더 말한다.',
